#!/usr/bin/env node

/**
 * ULS User Custom Component Deleter
 * 
 * Deletes a custom component from src/uls-components/src/custom-components/
 * and removes its export from index.js
 * 
 * Usage:
 *   uls -d component ComponentName
 *   node scripts/delete-component.js ComponentName
 */

const fs = require('fs');
const path = require('path');
const readline = require('readline');

// ==========================================================================
// UTILITY FUNCTIONS
// ==========================================================================

function generateComponentVariations(componentName) {
  const pascalCase = componentName.charAt(0).toUpperCase() + componentName.slice(1).replace(/-([a-z])/g, (g) => g[1].toUpperCase());
  const kebabCase = componentName.replace(/([A-Z])/g, '-$1').toLowerCase().replace(/^-/, '');
  
  return {
    ComponentName: pascalCase,
    kebabName: kebabCase
  };
}

function findProjectRoot() {
  let currentDir = process.cwd();
  
  // Look for src/uls-components directory
  while (currentDir !== path.dirname(currentDir)) {
    const ulsComponentsPath = path.join(currentDir, 'src', 'uls-components');
    if (fs.existsSync(ulsComponentsPath)) {
      return currentDir;
    }
    currentDir = path.dirname(currentDir);
  }
  
  // Fallback to current directory
  return process.cwd();
}

function findDemoAppPath() {
  const projectRoot = findProjectRoot();
  if (projectRoot) {
    const demoPath = path.join(projectRoot, 'src', 'demo', 'uls-primereact', 'src');
    if (fs.existsSync(demoPath)) {
      return demoPath;
    }
  }
  return null;
}

function removeExportFromIndex(projectRoot, componentName, variations) {
  const indexPath = path.join(projectRoot, 'src', 'uls-components', 'src', 'index.js');
  
  if (!fs.existsSync(indexPath)) {
    console.warn(`⚠️  Warning: index.js not found at: ${indexPath}`);
    return false;
  }
  
  let indexContent = fs.readFileSync(indexPath, 'utf8');
  const originalContent = indexContent;
  
  // Pattern to match export lines for this component
  // Matches: export { ComponentName } from './custom-components/kebab-name';
  const exportPattern = new RegExp(`export\\s+.*${variations.ComponentName}.*from\\s+['"]\\./custom-components/${variations.kebabName}['"];?\\s*\\n?`, 'gi');
  
  // Remove the export line
  indexContent = indexContent.replace(exportPattern, '');
  
  // Also check for any other variations (with or without default export)
  const defaultExportPattern = new RegExp(`export\\s+.*default.*from\\s+['"]\\./custom-components/${variations.kebabName}['"];?\\s*\\n?`, 'gi');
  indexContent = indexContent.replace(defaultExportPattern, '');
  
  // Only write if content changed
  if (indexContent !== originalContent) {
    fs.writeFileSync(indexPath, indexContent, 'utf8');
    return true;
  }
  
  return false;
}

function deleteDemoPage(demoAppPath, componentName, variations) {
  if (!demoAppPath) {
    return false;
  }
  
  const pageFolderName = `${variations.ComponentName}Page`;
  
  // Check for demo page in custom-demo folder
  const customDemoPath = path.join(demoAppPath, 'custom-demo', pageFolderName);
  const customComponentsPath = path.join(demoAppPath, 'custom-components', variations.ComponentName);
  
  // Check for registered page in UiComponents folder
  const uiComponentsPath = path.join(demoAppPath, 'Pages', 'Documentation', 'UiComponents', pageFolderName);
  
  let deleted = false;
  
  // Delete custom-demo page
  if (fs.existsSync(customDemoPath)) {
    fs.rmSync(customDemoPath, { recursive: true, force: true });
    console.log(`🗑️  Deleted demo page: ${path.relative(process.cwd(), customDemoPath)}`);
    deleted = true;
  }
  
  // Delete custom-components demo
  if (fs.existsSync(customComponentsPath)) {
    fs.rmSync(customComponentsPath, { recursive: true, force: true });
    console.log(`🗑️  Deleted demo component: ${path.relative(process.cwd(), customComponentsPath)}`);
    deleted = true;
  }
  
  // Delete registered page
  if (fs.existsSync(uiComponentsPath)) {
    fs.rmSync(uiComponentsPath, { recursive: true, force: true });
    console.log(`🗑️  Deleted registered page: ${path.relative(process.cwd(), uiComponentsPath)}`);
    deleted = true;
  }
  
  return deleted;
}

function askQuestion(question) {
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
  });
  
  return new Promise((resolve) => {
    rl.question(question, (answer) => {
      rl.close();
      resolve(answer.trim().toLowerCase());
    });
  });
}

// ==========================================================================
// MAIN DELETE FUNCTION
// ==========================================================================

async function deleteComponent(componentName, options = {}) {
  const { skipDemo = false, force = false } = options;
  
  try {
    if (!componentName) {
      console.error('❌ Error: Component name is required');
      console.log('\nUsage:');
      console.log('  uls -d component <ComponentName>');
      console.log('  node scripts/delete-component.js <ComponentName>');
      console.log('\nExamples:');
      console.log('  uls -d component MyButton');
      console.log('  uls -d component CustomCard');
      process.exit(1);
    }
    
    const projectRoot = findProjectRoot();
    const variations = generateComponentVariations(componentName);
    
    // Paths
    const customComponentsPath = path.join(projectRoot, 'src', 'uls-components', 'src', 'custom-components');
    const componentPath = path.join(customComponentsPath, variations.kebabName);
    
    // Check if component exists
    if (!fs.existsSync(componentPath)) {
      console.error(`❌ Error: Component ${variations.ComponentName} not found at:`);
      console.error(`   ${componentPath}`);
      console.log('\n💡 Tip: Make sure you are using the correct component name.');
      console.log('   Component names are case-insensitive but should match the original.');
      process.exit(1);
    }
    
    // Confirm deletion (unless force flag is set)
    if (!force) {
      console.log(`\n⚠️  You are about to delete component: ${variations.ComponentName}`);
      console.log(`   Location: ${path.relative(process.cwd(), componentPath)}`);
      
      const answer = await askQuestion('\nAre you sure you want to delete this component? (yes/no): ');
      if (answer !== 'yes' && answer !== 'y') {
        console.log('❌ Deletion cancelled.');
        process.exit(0);
      }
    }
    
    // Check for demo page
    const demoAppPath = findDemoAppPath();
    let hasDemoPage = false;
    if (demoAppPath) {
      const pageFolderName = `${variations.ComponentName}Page`;
      const customDemoPath = path.join(demoAppPath, 'custom-demo', pageFolderName);
      const customComponentsPath = path.join(demoAppPath, 'custom-components', variations.ComponentName);
      const uiComponentsPath = path.join(demoAppPath, 'Pages', 'Documentation', 'UiComponents', pageFolderName);
      
      hasDemoPage = fs.existsSync(customDemoPath) || 
                    fs.existsSync(customComponentsPath) || 
                    fs.existsSync(uiComponentsPath);
    }
    
    // Ask about demo page deletion (unless skipDemo flag is set)
    let deleteDemo = skipDemo ? false : false;
    if (hasDemoPage && !skipDemo && !force) {
      const answer = await askQuestion('\nDo you also want to delete the demo page? (yes/no): ');
      deleteDemo = answer === 'yes' || answer === 'y';
    } else if (hasDemoPage && !skipDemo) {
      deleteDemo = true; // Force mode - delete demo page too
    }
    
    // Delete component folder
    console.log(`\n🗑️  Deleting component: ${variations.ComponentName}...`);
    fs.rmSync(componentPath, { recursive: true, force: true });
    console.log(`   ✅ Deleted: ${path.relative(process.cwd(), componentPath)}`);
    
    // Remove export from index.js
    const exportRemoved = removeExportFromIndex(projectRoot, componentName, variations);
    if (exportRemoved) {
      console.log(`   ✅ Removed export from index.js`);
    } else {
      console.warn(`   ⚠️  Could not find export in index.js (may have been already removed)`);
    }
    
    // Delete demo page if requested
    if (deleteDemo && demoAppPath) {
      console.log(`\n🗑️  Deleting demo page...`);
      deleteDemoPage(demoAppPath, componentName, variations);
      console.log(`   ✅ Demo page deleted`);
    } else if (hasDemoPage && !deleteDemo) {
      console.log(`\n💡 Demo page still exists. To delete it manually:`);
      console.log(`   - Custom demo: ${path.join(demoAppPath, 'custom-demo', `${variations.ComponentName}Page`)}`);
      console.log(`   - Registered page: ${path.join(demoAppPath, 'Pages', 'Documentation', 'UiComponents', `${variations.ComponentName}Page`)}`);
    }
    
    console.log(`\n✅ Successfully deleted ${variations.ComponentName} component!`);
    console.log(`\n💡 Next steps:`);
    console.log(`   1. Restart your dev server if it's running`);
    console.log(`   2. Remove any imports of ${variations.ComponentName} from your code`);
    
  } catch (error) {
    console.error('\n❌ Error:', error.message);
    if (error.stack) {
      console.error('\nStack trace:', error.stack);
    }
    process.exit(1);
  }
}

// ==========================================================================
// CLI INTERFACE
// ==========================================================================

const componentName = process.argv[2];
const args = process.argv.slice(2);
const skipDemo = args.includes('--skip-demo');
const force = args.includes('--force');

deleteComponent(componentName, { skipDemo, force });

